using System.Text.Json; using GSPTaskMiningAnalyzer.Models; namespace GSPTaskMiningAnalyzer; public sealed class HtmlReportService { public string Write(AnalysisResult r,string output){Directory.CreateDirectory(output); var path=Path.Combine(output,$"task_mining_dashboard_{DateTime.Now:yyyyMMdd_HHmmss}.html"); var data=JsonSerializer.Serialize(new{active=r.ActiveSeconds,idle=r.IdleSeconds,apps=r.AppSeconds,sessions=r.Sessions.Take(500),chains=r.Chains2}); File.WriteAllText(path,$"""<!doctype html><html><head><meta charset="utf-8"><title>Task Mining Dashboard</title><style>body{{font-family:Arial;margin:24px}}.kpi{{display:inline-block;padding:12px;margin:6px;background:#eef}}table{{border-collapse:collapse}}td,th{{border:1px solid #ccc;padding:4px}}</style></head><body><h1>Task Mining Dashboard</h1><div id="kpi"></div><h2>Applications</h2><table id="apps"></table><h2>Sessions</h2><details open><summary>Timeline</summary><table id="sessions"></table></details><script>const data={data};function dur(s){{s=Math.round(s);let h=Math.floor(s/3600),m=Math.floor((s%3600)/60);return h?`${{h}} ч ${{m}} мин`:`${{m}} мин`;}}document.getElementById('kpi').innerHTML=`<span class=kpi>Active: ${{dur(data.active)}}</span><span class=kpi>Idle: ${{dur(data.idle)}}</span>`;apps.innerHTML='<tr><th>Application</th><th>Time</th></tr>'+Object.entries(data.apps).map(x=>`<tr><td>${{x[0]}}</td><td>${{dur(x[1])}}</td></tr>`).join('');sessions.innerHTML='<tr><th>Start</th><th>End</th><th>App</th><th>Title</th><th>Time</th></tr>'+data.sessions.map(s=>`<tr><td>${{s.Start}}</td><td>${{s.End}}</td><td>${{s.ProcessName}}</td><td>${{s.WindowTitle}}</td><td>${{dur(s.DurationSeconds)}}</td></tr>`).join('');</script></body></html>"""); return path;} }
